<?php
declare(strict_types=1);

namespace CTF\Server\Repositories;

use CTF\Server\Database\Connection;

/**
 * CRUD for `groups` table.
 *
 * Groups are owned by a single teacher (FK users.id). Each group has a
 * unique join_code used by students to join. Codes are generated by
 * GroupService (with retry on collision), not here.
 */
final class GroupRepository
{
    public const STATUS_ACTIVE   = 'active';
    public const STATUS_ARCHIVED = 'archived';

    /** @return array<string,mixed>|null */
    public function findById(int $id): ?array
    {
        return Connection::fetchOne('SELECT * FROM `groups` WHERE id = :id', [':id' => $id]);
    }

    /** @return array<string,mixed>|null */
    public function findByUuid(string $uuid): ?array
    {
        return Connection::fetchOne('SELECT * FROM `groups` WHERE uuid = :u', [':u' => $uuid]);
    }

    /** @return array<string,mixed>|null */
    public function findByJoinCode(string $code): ?array
    {
        return Connection::fetchOne(
            'SELECT * FROM `groups` WHERE join_code = :c',
            [':c' => strtoupper($code)]
        );
    }

    /**
     * @param array<string,mixed> $fields Required: uuid, teacher_id, name, join_code.
     *                                     Optional: description, max_members, status.
     * @return int New group id.
     */
    public function create(array $fields): int
    {
        foreach (['uuid', 'teacher_id', 'name', 'join_code'] as $k) {
            if (empty($fields[$k])) {
                throw new \InvalidArgumentException("Missing field: {$k}");
            }
        }
        Connection::run(
            'INSERT INTO `groups`
                (uuid, teacher_id, name, description, join_code, max_members, status)
             VALUES
                (:u, :t, :n, :d, :c, :m, :s)',
            [
                ':u' => (string)$fields['uuid'],
                ':t' => (int)$fields['teacher_id'],
                ':n' => (string)$fields['name'],
                ':d' => isset($fields['description']) ? (string)$fields['description'] : null,
                ':c' => strtoupper((string)$fields['join_code']),
                ':m' => isset($fields['max_members']) && $fields['max_members'] !== null
                        ? (int)$fields['max_members'] : null,
                ':s' => $fields['status'] ?? self::STATUS_ACTIVE,
            ]
        );
        return (int)Connection::pdo()->lastInsertId();
    }

    public function updateStatus(int $id, string $status): bool
    {
        $affected = Connection::run(
            'UPDATE `groups` SET status = :s WHERE id = :id',
            [':s' => $status, ':id' => $id]
        )->rowCount();
        return $affected > 0;
    }

    /**
     * Regenerate join_code. Returns true on success.
     * Caller MUST have generated $newCode via GroupService::generateUniqueJoinCode().
     */
    public function updateJoinCode(int $id, string $newCode): bool
    {
        $affected = Connection::run(
            'UPDATE `groups` SET join_code = :c WHERE id = :id',
            [':c' => strtoupper($newCode), ':id' => $id]
        )->rowCount();
        return $affected > 0;
    }

    public function delete(int $id): bool
    {
        $affected = Connection::run(
            'DELETE FROM `groups` WHERE id = :id',
            [':id' => $id]
        )->rowCount();
        return $affected > 0;
    }

    /**
     * List all groups owned by a teacher (any status).
     * @return array<int,array<string,mixed>>
     */
    public function listByTeacher(int $teacherId): array
    {
        return Connection::fetchAll(
            'SELECT g.*, COUNT(gm.id) AS member_count
             FROM `groups` g
             LEFT JOIN group_members gm
                    ON gm.group_id = g.id AND gm.status = :active
             WHERE g.teacher_id = :t
             GROUP BY g.id
             ORDER BY g.created_at DESC, g.id DESC',
            [':t' => $teacherId, ':active' => 'active']
        );
    }

    /**
     * Count active members of a group.
     */
    public function countActiveMembers(int $groupId): int
    {
        $row = Connection::fetchOne(
            'SELECT COUNT(*) AS c FROM group_members
             WHERE group_id = :g AND status = :s',
            [':g' => $groupId, ':s' => 'active']
        );
        return (int)($row['c'] ?? 0);
    }
}
